  console.error(err);
  res.status(500).json({ error: 'Internal Server Error' });
});

const PORT = parseInt(process.env.PORT || '3000', 10);
if (Number.isNaN(PORT) || PORT < 1 || PORT > 65535) {
  throw new Error('Invalid PORT');
}

app.listen(PORT, () => {
