      .isLength({ min: 1, max: 100 })
      .matches(/^[a-zA-Z\s'-]+$/),
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const { name } = req.query;
    // Safe use of validated input here
    res.json({ message: `Searching for ${name}` });
  }
);
```

