```js
const express = require('express');
const app = express();

function requireApiKey(req, res, next) {
  const apiKey = req.get('x-api-key');

  if (!apiKey || apiKey !== process.env.API_KEY) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  next();
}

app.get('/users', requireApiKey, (req, res) => {
  res.json([
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ]);
});
```

### Better practice
Use a real auth solution such as:

- JWT validation with proper signature verification
- Session-based auth
- OAuth/OIDC via a trusted identity provider

And also add **role-based authorization**, e.g. only admins can list all users.

